import pandas as pd
import numpy as np


def _sig_val(v):
    if pd.isna(v):
        v = ""
    else:
        v = str(v)
    return v.rstrip()


def _sig(city, tier):
    return _sig_val(city) + "|" + _sig_val(tier)


def run(inputs: dict) -> dict:
    dim = inputs["DIM_MEMBER"].copy()
    stg = inputs["STG_MEMBER"].copy()

    # Ensure expected columns exist, preserve dtypes as much as possible.
    cols = ["member_id", "city", "tier", "eff_start_date", "eff_end_date", "is_current"]
    for c in cols:
        if c not in dim.columns:
            dim[c] = pd.NA

    dim = dim.reset_index(drop=True)

    # Build a lookup of current row index per member_id (first match if multiple).
    current_idx_by_member = {}
    for idx, row in dim.iterrows():
        if row.get("is_current") == 1:
            mid = row["member_id"]
            if mid not in current_idx_by_member:
                current_idx_by_member[mid] = idx

    new_rows = []

    for _, s in stg.iterrows():
        mid = s["member_id"]
        s_city = s.get("city", pd.NA)
        s_tier = s.get("tier", pd.NA)
        s_update_date = s.get("update_date", pd.NA)

        if mid in current_idx_by_member:
            idx = current_idx_by_member[mid]
            c_city = dim.at[idx, "city"]
            c_tier = dim.at[idx, "tier"]

            sig_s = _sig(s_city, s_tier)
            sig_c = _sig(c_city, c_tier)

            if sig_s != sig_c:
                # close out current row
                dim.at[idx, "eff_end_date"] = s_update_date
                dim.at[idx, "is_current"] = 0

                new_rows.append({
                    "member_id": mid,
                    "city": s_city,
                    "tier": s_tier,
                    "eff_start_date": s_update_date,
                    "eff_end_date": pd.NA,
                    "is_current": 1,
                })
            # else: no-op, keep c as is
        else:
            # no current row for this member -> insert new
            new_rows.append({
                "member_id": mid,
                "city": s_city,
                "tier": s_tier,
                "eff_start_date": s_update_date,
                "eff_end_date": pd.NA,
                "is_current": 1,
            })

    if new_rows:
        new_df = pd.DataFrame(new_rows, columns=cols)
        result = pd.concat([dim[cols], new_df], ignore_index=True)
    else:
        result = dim[cols].copy()

    return {"dim_member_out": result}
